if ($this->customer->isLogged()) {
	$this->load->model('account/wishlist');
	$data['wishlistdata'] = $this->model_account_wishlist->getWishlistProducts();
} else {
	$wishlist = isset($_COOKIE['cookieWishlist']) ? json_decode($_COOKIE['cookieWishlist'],1) : [];
	$data['wishlistdata'] = array_unique($wishlist);
}

$data['comparedata'] = isset($this->session->data['compare']) ? $this->session->data['compare'] : array();


